const arrow=(x,y,x2,y2,label='',color=c.cyan)=>`<path d="M${x} ${y}L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="1.7" marker-end="url(#a-${Object.keys(c).find(k=>c[k]===color)||'cyan'})"/>${label?text((x+x2)/2,(y+y2)/2-11,label,12,c.muted):''}`;
const path=(d,color=c.cyan,dash='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="1.7" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const circle=(x,y,r,color=c.cyan,opacity=1)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}" opacity="${opacity}"/>`;
const phase=(n,step,body)=>`<g opacity="${n<=step?1:.16}" class="phase">${body}</g>`;
const num=(x,y,n)=>circle(x,y,13,c.gold,.14)+text(x,y+5,n,13,c.gold);
const wrap=(id,body)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 540" font-family="Presentation Sans,Arial,sans-serif" role="img" aria-label="Подробная схема: ${id}"><defs>${['cyan','gold','coral','purple'].map(k=>`<marker id="a-${k}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M1 1L7 4L1 7" fill="none" stroke="${c[k]}" stroke-width="1.4"/></marker>`).join('')}<pattern id="dots" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#344756"/></pattern></defs><rect width="960" height="540" fill="url(#dots)" opacity=".5"/>${body}</svg>`;
function matrix(x,y,values,cell=38,color=c.cyan,labels=[]){let s='';values.forEach((row,i)=>row.forEach((v,j)=>{s+=`<rect x="${x+j*cell}" y="${y+i*cell}" width="${cell-3}" height="${cell-3}" rx="3" fill="${color}" opacity="${v===null?.025:.1+Math.abs(v)*.7}"/>`;if(v!==null)s+=text(x+j*cell+(cell-3)/2,y+i*cell+cell*.58,typeof v==='number'?Number(v.toFixed(2)):v,cell>35?12:10,c.white)}));labels.forEach((t,i)=>{s+=text(x-9,y+i*cell+cell*.58,t,11,c.muted,'end')+text(x+i*cell+cell/2,y-12,t,11,c.muted)});return s}
function pixel(x,y,n,size=8,noise=0){let s='';for(let i=0;i<n;i++)for(let j=0;j<n;j++){const r=Math.sqrt((i-(n-1)/2)**2+(j-(n-1)/2)**2),shape=(r<n*.35&&r>n*.15)?1:.08,rand=Math.abs(Math.sin(i*87+j*134)*1943)%1,val=shape*(1-noise)+rand*noise;s+=`<rect x="${x+j*size}" y="${y+i*size}" width="${size}" height="${size}" fill="${val>.5?c.cyan:'#172938'}" opacity="${.3+val*.7}"/>`}return s}
function network(x,y,cols=[3,5,3],w=310,h=210){let s='';const coords=cols.map((n,l)=>Array.from({length:n},(_,j)=>[x+l*w/(cols.length-1),y+h/2+(j-(n-1)/2)*(h/(Math.max(...cols)-1))]));coords.forEach((col,l)=>col.forEach(p=>{if(l<cols.length-1)coords[l+1].forEach(q=>s+=path(`M${p[0]} ${p[1]}L${q[0]} ${q[1]}`,'#344756'));}));coords.flat().forEach(p=>s+=circle(...p,7,c.cyan));return s}
export function softmax(xs){let m=Math.max(...xs),e=xs.map(x=>Math.exp(x-m)),sum=e.reduce((a,b)=>a+b,0);return e.map(x=>x/sum)}
export const toyQ=[[1,0],[0,1],[1,1],[.5,-.5]],toyK=[[1,0],[0,1],[1,1],[-1,.5]],toyV=[[1,0],[0,1],[1,1],[.2,.8]];
export function attentionWeights(row){return softmax(toyK.map(k=>(k[0]*toyQ[row][0]+k[1]*toyQ[row][1])/Math.sqrt(2)))}
export function heatSolution(x,t){return Math.sin(Math.PI*x)*Math.exp(-.3*Math.PI*Math.PI*t)}
